            raise ValueError("questions cannot be negative")

        if self.correct < 0:
            raise ValueError("correct cannot be negative")

        if self.wrong < 0:
            raise ValueError("wrong cannot be negative")

        if self.correct + self.wrong > self.questions:
            raise ValueError(
