import socket
import struct

# -------------------- SOCKET HELPERS --------------------
def read_packet(sock):
    header = read_exact(sock, 4)
    length = header[0] | (header[1] << 8) | (header[2] << 16)
    seq = header[3]
    payload = read_exact(sock, length)
    return seq, payload

def read_exact(sock, n):
    data = b""
    while len(data) < n:
        chunk = sock.recv(n - len(data))
        if not chunk:
            raise ConnectionError("Connection closed")
        data += chunk
    return data

def write_packet(sock, payload, seq=1):
    length = len(payload)
    header = struct.pack("<I", length)[:3] + bytes([seq])
    sock.sendall(header + payload)

# ==================== PACKET WRITER ====================
def setup_writer_funcs(class_):
    class_.writers =  [
            class_.write_int,
            class_.write_string,
            class_.write_lenenc_int,
            class_.write_lenenc_string
        ]
    return class_

@setup_writer_funcs
class PayloadWriter:
    class DataType:
        INT = 0
        STRING = 1
        INT_LENENC = 2
        STR_LENENC = 3
    # the writers list is filled after class instantiation by called setup_writer_funcs decorator
    writers = []

    @staticmethod
    def create_payload(formats:list) -> bytes:
        # each element of formats is [data,PayloadWriter.DataType,bytes]
        payload = b''
        for data, type_, bytes_ in formats:
            writer = PayloadWriter.writers[type_]
            o = writer(data, bytes_)
            if o is None:
                raise ValueError("Format error")
            payload += o
        return payload

    @staticmethod
    def write_int(data: int, bytes_: int) -> bytes:
        return data.to_bytes(bytes_, byteorder="little", signed=False)

    @staticmethod
    def write_string(data: str, bytes_: int = -1) -> bytes:
        encoded = data.encode()

        if bytes_ == -1:  # Null-terminated
            return encoded + b'\x00'
        elif bytes_ == 0:  # Until EOF
            return encoded
        else:  # Fixed length
            return encoded.ljust(bytes_, b'\x00')[:bytes_]

    # -------- Length Encoded --------
    @staticmethod
    def write_lenenc_int(data: int, _) -> bytes:
        if data < 0xfb:
            return struct.pack("<B", data)
        elif data <= 0xFFFF:
            return b'\xfc' + struct.pack("<H", data)
        elif data <= 0xFFFFFF:
            return b'\xfd' + struct.pack("<I", data)[:3]
        else:
            return b'\xfe' + struct.pack("<Q", data)

    @staticmethod
    def write_lenenc_string(data: str, _) -> bytes:
        encoded = data.encode()
        length_part = PayloadWriter.write_lenenc_int(len(encoded), None)
        return length_part + encoded


# ==================== PACKET PARSER ====================
def setup_reader_funcs(PayloadParser):
    PayloadParser.readers = [PayloadParser.read_int,PayloadParser.read_string,PayloadParser.read_lenenc_int,PayloadParser.read_lenenc_string]
    return PayloadParser

@setup_reader_funcs
class PayloadParser:
    class DataType:
        INT = 0
        STRING = 1
        INT_LENENC = 2
        STR_LENENC = 3
    # the readers list is filled after class instantiation by called setup_reader_funcs decorator
    readers = []
    @staticmethod
    def parse(payload: bytes, formats):
        output = dict()
        offset = 0
        # each element of formats : (key:string,type : PayloadParser.DataType, size in bytes)
        for key, type_, size in formats:
            reader = PayloadParser.readers[type_]
            data, used = reader(payload[offset:], size)

            if used == 0:
                raise ValueError("Format error")

            offset += used
            output[key] = data

        return output,offset

    @staticmethod
    def read_int(payload: bytes, bytes_: int):
        val = int.from_bytes(payload[:bytes_], byteorder="little")
        return val, bytes_

    @staticmethod
    def read_string(payload: bytes, bytes_: int = -1):
        if bytes_ == -1:  # Null terminated
            end = payload.find(b'\x00')
            return payload[:end].decode(), end + 1
        elif bytes_ == 0:  # Until EOF
            return payload.decode(), len(payload)
        else:
            return payload[:bytes_].decode().rstrip('\x00'), bytes_

    # -------- Length Encoded --------
    @staticmethod
    def read_lenenc_int(payload: bytes, _):
        first = payload[0]

        if first < 0xfb:
            return first, 1
        elif first == 0xfc:
            return struct.unpack("<H", payload[1:3])[0], 3
        elif first == 0xfd:
            return int.from_bytes(payload[1:4], "little"), 4
        elif first == 0xfe:
            return struct.unpack("<Q", payload[1:9])[0], 9
        else:
            return None, 1  # NULL value in MySQL protocol

    @staticmethod
    def read_lenenc_string(payload: bytes, _):
        length, used = PayloadParser.read_lenenc_int(payload, None)
        start = used
        end = start + length
        return payload[start:end].decode(), used + length

