    print("=== MySQL Packet Writer/Parser Self-Test ===")

    # ---------------- Test Data ----------------
    original_data = {
        "int1": 250,
        "int2": 65535,
        "fixed_str": "Kruthi",
        "null_str": "HelloWorld",
        "lenenc_int": 123456,
        "lenenc_str": "MySQLProtocol"
    }

    # Format for WRITING (order matters)
    write_formats = [
        (original_data["int1"], PayloadWriter.DataType.INT, 1),
        (original_data["int2"], PayloadWriter.DataType.INT, 2),
        (original_data["fixed_str"], PayloadWriter.DataType.STRING, 10),   # fixed 10 bytes
        (original_data["null_str"], PayloadWriter.DataType.STRING, -1),   # null terminated
        (original_data["lenenc_int"], PayloadWriter.DataType.INT_LENENC, None),
        (original_data["lenenc_str"], PayloadWriter.DataType.STR_LENENC, None),
    ]

    payload = PayloadWriter.create_payload(write_formats)
    print(f"\nWritten Payload ({len(payload)} bytes):", payload)

    # Format for READING (must match order & types)
    read_formats = [
        ("int1", PayloadParser.DataType.INT, 1),
        ("int2", PayloadParser.DataType.INT, 2),
        ("fixed_str", PayloadParser.DataType.STRING, 10),
        ("null_str", PayloadParser.DataType.STRING, -1),
        ("lenenc_int", PayloadParser.DataType.INT_LENENC, None),
        ("lenenc_str", PayloadParser.DataType.STR_LENENC, None),
    ]

    parsed_data = PayloadParser.parse(payload, read_formats)

